import{z as l,x as d,o as E,c as B,q as o,j as A,D as t,d as n,s,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"工具变量在金融","description":"","frontmatter":{"title":"工具变量在金融","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/iv-finance.md","filePath":"quant/iv-finance.md","lastUpdated":1791063341000}'),p={name:"quant/iv-finance.md"};function h(u,a,S,m,c,F){const r=d("Mermaid");return E(),B("div",null,[a[2]||(a[2]=o('<h1 id="工具变量在金融" tabindex="-1">工具变量在金融 <a class="header-anchor" href="#工具变量在金融" aria-label="Permalink to &quot;工具变量在金融&quot;">​</a></h1><div class="epigraph"><p>回归元与误差相关时，最小二乘估的是混合物；找一个只通过该回归元进入结果的外生变动，才能把因果斜率从相关里拆出来——前提是排除限制真的成立。</p><footer>—— 识别表述见 Angrist, Imbens and Rubin 的 LATE 框架；金融应用的常见失败见 Roberts and Whited 对公司金融识别的综述</footer></div><p><a href="/quant/panel-fe-finance">面板固定效应</a> 消掉不随时间变的 \\(c_i\\)，组内仍可能内生：投资与现金流同时被投资机会驱动，估值与预期收益同时被风险驱动，分析师覆盖与流动性同时被关注度驱动。工具变量把 \\(x\\) 的变动拆成「与 \\(u\\) 相关的」和「只通过 \\(x\\) 的」。本课缺口是金融 IV 的<strong>排除限制几乎总是可争的</strong>，弱工具会把 2SLS 变成噪声放大器。后课事件研究用时间上的集中冲击，是另一种外生变动，不是 IV 的替代写法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(y=x\\beta+u\\)，\\(E[xu]\\neq 0\\)。工具 \\(z\\) 满足相关 \\(E[zx]\\neq 0\\)、排除 \\(E[zu]=0\\)。2SLS 先用 \\(z\\) 投影 \\(x\\)，再用 \\(\\hat x\\) 回归 \\(y\\)。估计的是对工具诱导的那部分变动的加权（LATE：谁被 \\(z\\) 推动，权重在谁身上）。问题不是「找一个相关的 \\(z\\)」，而是 <strong>\\(z\\) 是否只通过 \\(x\\) 影响 \\(y\\)</strong>。</p><p>金融里常见伪工具：滞后 \\(x\\) 当工具（序列相关的 \\(u\\) 仍相关）、行业均值当工具（行业冲击直接进 \\(y\\)）、指数纳入当工具（纳入本身改变需求与关注，排除失败）。Roberts 与 Whited 强调：写故事容易，证伪排除难。</p><p><span class="marginnote">术语翻译：工具变量方法就是「找一个只通过 \\(x\\) 间接影响 \\(y\\) 的外生变动，再顺着这股变动测斜率」的手段。可以想象成测水管口径时故意在水表前开一个小阀门（工具 \\(z\\)），只看这个阀门引起的流量变化来反推管径，从而绕开住户用水习惯（误差 \\(u\\)）的干扰。</span></p><h3 id="弱工具先于内生讨论" tabindex="-1">弱工具先于内生讨论 <a class="header-anchor" href="#弱工具先于内生讨论" aria-label="Permalink to &quot;弱工具先于内生讨论&quot;">​</a></h3><p>第一阶段 \\(F\\) 小，2SLS 向 OLS 偏、方差膨胀、非正态。Stock–Yogo 临界值、Anderson–Rubin 对弱工具稳健的检验，应先于「IV 显著」的叙述。多个工具时过度识别的 Hansen–Sargan 检验拒绝，说明至少一个排除失败；不拒绝并不能证明排除成立——功效可以很弱。</p><p><span class="marginnote">数字实例：第一阶段 \\(F\\) 低于 10 是常用预警线；\\(F\\) 只有 3 时，2SLS 的有限样本偏差可达 OLS 量级，95% 置信区间名存实亡。初学者容易只盯第二阶段的 p 值——实际上第一阶段不够强，后面所有推断都建在流沙上。</span></p><p><span class="marginnote">「相关所以是好工具」是第一阶段；好工具还要排除。把第一阶段 \\(t\\) 当识别证据，是把相关当成因果的另一种写法。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>2SLS 与 GMM。</strong> 恰好识别时两者等价。过度识别用 Hansen 的 GMM 加权，标准误用稳健或聚类——IV 不豁免 <a href="/quant/clustered-se">聚类</a>。有限样本里 2SLS 偏小（朝 OLS），LIML 对弱工具稍稳，报告两者。</p><p><strong>金融里还算干净的设计（仍要逐项争）。</strong> 指数重组、合并带来的外生持仓变化（但需求冲击可直接进收益）；地理或监管门槛（但门槛常与发展程度共变）；天气、灾害作为局部冲击（但可影响基本面）。没有「资产定价专用的标准工具包」可以自动用于 \\(\\beta\\) 或特征。</p><p><strong>与 <a href="/quant/fama-macbeth">Fama–MacBeth</a>。</strong> FM 不管内生。用特征当 \\(x\\) 解释收益，特征若是被定价的风险代理，OLS 估的是预测关系，不必假装是结构弹性。只有当你声称「治理导致价值」而治理由预期价值决定时，才进入 IV。对象先写清：预测还是因果。</p><h3 id="诊断清单" tabindex="-1">诊断清单 <a class="header-anchor" href="#诊断清单" aria-label="Permalink to &quot;诊断清单&quot;">​</a></h3><p>报告第一阶段、排除的经济论证、弱工具稳健区间、聚类维与 FE 集合。安慰剂：工具对不应该被影响的结果。简化型 \\(y\\) 对 \\(z\\)：若简化型为零，无论 2SLS 多好看都没有第一阶段故事。不要只报告 2SLS 点估计。</p>',17)),(E(),A(i,null,{default:t(()=>[s(r,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E5%80%99%E9%80%89%E5%B7%A5%E5%85%B7%20z%22%5D%20--%3E%20E%7B%22%E6%8E%92%E9%99%A4%E8%AE%BA%E8%AF%81%E8%83%BD%E5%90%A6%E8%AE%B2%E9%80%9A%3F%22%7D%0A%20%20E%20--%20%22%E5%90%A6%22%20--%3E%20Drop%5B%22%E6%94%BE%E5%BC%83%2C%20%E6%8D%A2%E8%AE%BE%E8%AE%A1%22%5D%0A%20%20E%20--%20%22%E6%98%AF%22%20--%3E%20F%5B%22%E6%8A%A5%E5%91%8A%E7%AC%AC%E4%B8%80%E9%98%B6%E6%AE%B5%20F%20%E7%BB%9F%E8%AE%A1%E9%87%8F%22%5D%0A%20%20F%20--%3E%20FW%7B%22F%20%E5%A4%9F%E5%BC%BA%3F%22%7D%0A%20%20FW%20--%20%22%E5%90%A6%22%20--%3E%20AR%5B%22%E6%94%B9%E7%94%A8%E5%BC%B1%E5%B7%A5%E5%85%B7%E7%A8%B3%E5%81%A5%E7%9A%84%20AR%20%E5%8C%BA%E9%97%B4%22%5D%0A%20%20FW%20--%20%22%E6%98%AF%22%20--%3E%20OD%7B%22%E5%A4%9A%E5%B7%A5%E5%85%B7%3F%20%E5%81%9A%E8%BF%87%E5%BA%A6%E8%AF%86%E5%88%AB%E6%A3%80%E9%AA%8C%22%7D%0A%20%20OD%20--%3E%20R%5B%22%E5%B9%B6%E6%8A%A5%20OLS%20%2F%202SLS%20%2F%20AR%20%E5%8C%BA%E9%97%B4%22%5D%0A%20%20AR%20--%3E%20R%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>2SLS 的分子是 \\(z\\) 与 \\(y\\) 的协方差，分母是 \\(z\\) 与 \\(x\\) 的协方差。排除保证分子里没有 \\(z\\to u\\) 的直接通道。弱工具让分母接近零，比值的分布变成 Cauchy 类，正态 \\(t\\) 崩溃。这就是为什么 \\(F\\) 必须先看。</p><p>面板 IV：组内变换后用滞后水平当工具（Arellano–Bond）依赖序列不相关的 \\(u\\)；金融残差很少那么干净，差分 GMM 容易弱工具加错误排除。系统 GMM 再加水平方程，工具膨胀，Hansen 检验被过多工具买通。公司金融里应少工具、长差异，而不是默认 <code>xtabond2</code> 全套滞后。</p><p><span class="marginnote">Wald 比率直觉：\\(\\hat\\beta=\\widehat{\\mathrm{Cov}}(z,y)/\\widehat{\\mathrm{Cov}}(z,x)\\)。两个协方差都用同一聚类结构估计。分子分母的有限样本噪声会相关，这是 AR 检验直接测简化型的原因。</span></p><p><span class="marginnote">数字实例：若 \\(\\widehat{\\mathrm{Cov}}(z,y)=0.4\\)、\\(\\widehat{\\mathrm{Cov}}(z,x)=2.0\\)，Wald 比率就是 \\(0.4/2.0=0.2\\)。分母缩到 \\(0.02\\) 时，同样的分子噪声会把估计放大一百倍——这就是「弱工具把 2SLS 变成噪声放大器」的算术含义。</span></p><h3 id="资产定价中的「特征内生」" tabindex="-1">资产定价中的「特征内生」 <a class="header-anchor" href="#资产定价中的「特征内生」" aria-label="Permalink to &quot;资产定价中的「特征内生」&quot;">​</a></h3><p>账面市值比含价格，用它解释收益有机械成分。IV 很难找到只动基本面不动折现率的 \\(z\\)。更常见的处理是：承认预测回归、用稳健推断、或把特征写成载荷的代理（IPCA），而不是硬找一个「外生的账面」。把 IV 用在错误对象上，排除故事会变成形而上学。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>弱工具 + 聚类 + FE 的有限样本，自助须对整簇重抽并重做两阶段。异质 \\(\\beta\\) 时 2SLS 是 LATE，外推到未受工具推动的公司是额外假设。高频里用微观结构变量当工具（买卖压力解释收益）常常是定义而非排除。</p><p>工程：先写因果图再找 \\(z\\)；\\(F\\) 过线再谈 2SLS；并列 OLS、2SLS、AR 区间。不要用 20 个滞后当工具再声称过度识别通过。不要把指数纳入 IV 用在纳入日附近的事件收益上还假装排除——那更像 <a href="/quant/event-study">事件研究</a>。</p>',10)),(E(),A(i,null,{default:t(()=>[s(r,{id:"mermaid-80",class:"mermaid",graph:"flowchart%20TD%0A%20%20Z%5B%22%E5%B7%A5%E5%85%B7%20z%22%5D%20--%3E%20X%5B%22%E5%86%85%E7%94%9F%20x%22%5D%0A%20%20X%20--%3E%20Y%5B%22%E7%BB%93%E6%9E%9C%20y%22%5D%0A%20%20U%5B%22%E8%AF%AF%E5%B7%AE%20u%22%5D%20--%3E%20Y%0A%20%20U%20-.-%3E%7C%22%E7%9B%B8%E5%85%B3%E5%88%99%20OLS%20%E5%81%8F%22%7C%20X%0A%20%20Z%20-.-%3E%7C%22%E6%8E%92%E9%99%A4%3A%20%E4%B8%8D%E8%AE%B8%E7%9B%B4%E9%80%9A%22%7C%20Y%0A%20%20Z%20--%3E%20FS%5B%22%E7%AC%AC%E4%B8%80%E9%98%B6%E6%AE%B5%20F%22%5D%0A%20%20FS%20--%3E%20W%7B%22%E5%BC%B1%3F%22%7D%0A%20%20W%20--%3E%7C%E6%98%AF%7C%20AR%5B%22Anderson-Rubin%20%E5%8C%BA%E9%97%B4%22%5D%0A%20%20W%20--%3E%7C%E5%90%A6%7C%20TS%5B%222SLS%20%2F%20GMM%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e("h2",{id:"小结",tabindex:"-1"},[n("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[5]||(a[5]=e("ul",null,[e("li",null,"组内 FE 之后仍内生，才轮到 IV；IV 估的是工具推动的那部分变动。"),e("li",null,"排除限制是识别，第一阶段 \\(F\\) 是能否用正态推断；弱工具时改 AR 一类。"),e("li",null,"金融里滞后变量、行业均值、指数纳入都常破坏排除，须逐项论证。"),e("li",null,"预测问题不必硬套 IV；因果问题不能只用稳健标准误。"),e("li",null,[n("出处：两阶段与 LATE 见 Angrist and Imbens 相关工作；弱工具见 Stock and Yogo；金融识别综述见 Roberts and Whited；过度识别见 Hansen, "),e("em",null,"Econometrica"),n(", 1982。")])],-1))])}const C=l(p,[["render",h]]);export{f as __pageData,C as default};
